import{_ as s,o as n,c as e,a2 as i}from"./chunks/framework.D7EuCHIT.js";const u=JSON.parse('{"title":"插件开发环境","description":"","frontmatter":{},"headers":[],"relativePath":"developers/build.md","filePath":"developers/build.md","lastUpdated":1791818085000}'),l={name:"developers/build.md"};function p(r,a,t,d,o,c){return n(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="插件开发环境" tabindex="-1">插件开发环境 <a class="header-anchor" href="#插件开发环境" aria-label="Permalink to &quot;插件开发环境&quot;">​</a></h1><p>只需公开 SDK、Android NDK 和安装好的 Lyra Player。没有播放器源码前置条件，也不需要 Android 应用 keystore。插件 ZIP 不是 APK。</p><h2 id="环境清单" tabindex="-1">环境清单 <a class="header-anchor" href="#环境清单" aria-label="Permalink to &quot;环境清单&quot;">​</a></h2><ul><li>Linux 主机、Bash、Python 3.11+、ripgrep、Git（按需）。</li><li>Android SDK；教程使用 NDK 28.2.13676358。</li><li>arm64-v8a / API 26+ 的 Lyra Player 宿主和测试设备。</li><li>本站 <a href="/LyraPlayer-docs-site/downloads/lyra-plugin-sdk.zip">SDK 2 与示例包</a>。</li></ul><p>Windows/macOS 可使用对应 NDK toolchain，但随站提供的脚本目前验证的是 Linux 路径；不能直接把 linux-x86_64 路径复制到其他平台。</p><h2 id="编译三个示例" tabindex="-1">编译三个示例 <a class="header-anchor" href="#编译三个示例" aria-label="Permalink to &quot;编译三个示例&quot;">​</a></h2><p>解压 SDK 包或使用文档 workspace：</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ANDROID_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/Android/Sdk&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/build.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>产物：<code>out/examples/example.root.zip</code>、<code>example.style.zip</code>、<code>example.rules.zip</code>。脚本可用 <code>LYRA_NDK_VERSION</code> 选择 NDK。它不链接宿主 C++ 隐藏符号，不构建或签名播放器 APK。</p><p>在 Lyra 设置 → 安装插件选择 ZIP。先测试 style/rules，确认插件活动、参数及卸载恢复；根示例只演示 UI 接管。</p><h2 id="自己的项目" tabindex="-1">自己的项目 <a class="header-anchor" href="#自己的项目" aria-label="Permalink to &quot;自己的项目&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-plugin/</span></span>
<span class="line"><span>  sdk/include/plugin/  # 固定所依赖的公开 SDK</span></span>
<span class="line"><span>  src/plugin.c</span></span>
<span class="line"><span>  manifest.toml</span></span>
<span class="line"><span>  README.md</span></span>
<span class="line"><span>  CHANGELOG.md</span></span>
<span class="line"><span>  icon.png</span></span>
<span class="line"><span>  build.sh</span></span>
<span class="line"><span>  out/                 # 不入 Git</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>用 NDK 的 <code>aarch64-linux-android26-clang</code> 编译 <code>-std=c11 -fPIC -shared -fvisibility=hidden</code>，include 指向 sdk/include，明确导出 <code>lyra_plugin_init</code>。C++ 同样跨库使用 C ABI 与 POD，入口需要 extern C。</p><p>记录 SDK ABI、宿主版本和测试设备。自定义新接口 ID 不会让现有闭源宿主自动支持它；必须查询已经发布的能力。</p><p>下一步：<a href="/LyraPlayer-docs-site/plugins/first-plugin">第一个插件</a>。</p>`,15)])])}const b=s(l,[["render",p]]);export{u as __pageData,b as default};
